  ('shampooing-aloe-vera', 'shampooing-aloe-vera', 'hair', 'Atlas Botanica', '{"fr":"Shampooing hydratant aloe vera","en":"Aloe vera moisturising shampoo","ar":"شامبو مرطب بالصبار"}'::jsonb, '{"fr":"Une base lavante douce à l’aloe vera qui hydrate les longueurs sans les alourdir. Pour un usage quotidien.","en":"A gentle aloe vera wash that hydrates the lengths without weighing them down. For everyday use.","ar":"تركيبة لطيفة بالصبار ترطب الشعر دون أن تثقله. مناسب للاستعمال اليومي."}'::jsonb, '{"fr":"Appliquer sur cheveux mouillés ou secs selon le produit, masser doucement puis rincer si nécessaire.","en":"Apply to wet or dry hair depending on the product, massage gently, then rinse if needed.","ar":"يوضع على الشعر المبلل أو الجاف حسب المنتج، يدلك بلطف ثم يشطف عند الحاجة."}'::jsonb, null, '400 ml', 75, null, 28, true, false, false, 'pump', 7.5, 23, 7.5, 'products/shampooing-aloe-vera.webp', '{}'::text[], 'wall-hair', 0, 0, 2, false),
